// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
    wheatGold: make('smooth-structure', 'regolith-light'),
  };
}
// ---- end style header ----

const meta = {
  name: 'seed-packet-wheat',
  role: 'prop',
  reference: 'models and assets images/seed-packet-wheat.webp'
};

async function build() {
  const root = createRoot('seed-packet-wheat');
  defineBudget({ triangles: BUDGETS['small-prop'] }, root);

  const m = styleMaterials();

  // Dimensions: 0.024 x 0.18 x 0.12 m
  // Ground contact: Y = 0, front faces +X
  const pW = 0.118;
  const pH = 0.176;
  const pD = 0.022;
  const halfW = pW * 0.5;

  const envelopeNode = createPivot('envelope', [0, 0, 0], root);

  // 1. Main Envelope Pouch Body
  const cBot = 0.020;
  const centerY = pH * 0.5;
  const pouchProfile = [
    [-halfW, centerY],
    [halfW, centerY],
    [halfW, -centerY + cBot],
    [halfW - cBot, -centerY],
    [-halfW + cBot, -centerY],
    [-halfW, -centerY + cBot]
  ];

  const pouchGeo = await extrudeProfile(pouchProfile, {
    depth: pD,
    axis: 'x',
    center: true
  });
  createPart('PouchBody', pouchGeo, m.panel, {
    parent: envelopeNode,
    position: [0, centerY, 0]
  });

  // 2. Top Folded Cuff
  const cuffH = 0.024;
  const cuffW = pW + 0.006;
  const cuffD = pD + 0.006;
  const cuffY = pH - cuffH * 0.5 + 0.002;
  const cuffProfile = [
    [-cuffW * 0.5 + 0.008, cuffH * 0.5],
    [cuffW * 0.5 - 0.008, cuffH * 0.5],
    [cuffW * 0.5, cuffH * 0.5 - 0.008],
    [cuffW * 0.5, -cuffH * 0.5 + 0.008],
    [cuffW * 0.5 - 0.008, -cuffH * 0.5],
    [-cuffW * 0.5 + 0.008, -cuffH * 0.5],
    [-cuffW * 0.5, -cuffH * 0.5 + 0.008],
    [-cuffW * 0.5, cuffH * 0.5 - 0.008]
  ];
  const cuffGeo = await extrudeProfile(cuffProfile, {
    depth: cuffD,
    axis: 'x',
    center: true
  });
  createPart('TopCuff', cuffGeo, m.panel, {
    parent: envelopeNode,
    position: [0.002, cuffY, 0]
  });

  // Center Orange Seal Tape
  const tapeGeo = boxGeo(cuffD + 0.002, cuffH + 0.002, 0.028);
  createPart('OrangeSealTape', tapeGeo, m.accent, {
    parent: envelopeNode,
    position: [0.002, cuffY, 0]
  });

  // 3. Front Face Label Framing (Seamless extruded hollow octagon)
  const labelX = pD * 0.5 + 0.0012;
  const labelNode = createPivot('label', [labelX, 0, 0], envelopeNode);

  const bW = 0.092;
  const bH = 0.126;
  const bC = 0.016;
  const borderProfile = [
    [-bW * 0.5 + bC, bH * 0.5],
    [bW * 0.5 - bC, bH * 0.5],
    [bW * 0.5, bH * 0.5 - bC],
    [bW * 0.5, -bH * 0.5 + bC],
    [bW * 0.5 - bC, -bH * 0.5],
    [-bW * 0.5 + bC, -bH * 0.5],
    [-bW * 0.5, -bH * 0.5 + bC],
    [-bW * 0.5, bH * 0.5 - bC]
  ];

  const t = 0.006;
  const iW = bW - t * 2;
  const iH = bH - t * 2;
  const iC = Math.max(0.004, bC - t);
  const borderHole = [
    [-iW * 0.5 + iC, iH * 0.5],
    [iW * 0.5 - iC, iH * 0.5],
    [iW * 0.5, iH * 0.5 - iC],
    [iW * 0.5, -iH * 0.5 + iC],
    [iW * 0.5 - iC, -iH * 0.5],
    [-iW * 0.5 + iC, -iH * 0.5],
    [-iW * 0.5, -iH * 0.5 + iC],
    [-iW * 0.5, iH * 0.5 - iC]
  ];

  const borderGeo = await extrudeProfile(borderProfile, {
    holes: [borderHole],
    depth: 0.0018,
    axis: 'x',
    center: false
  });
  createPart('OrangeBorder', borderGeo, m.accent, {
    parent: labelNode,
    position: [0, centerY, 0]
  });

  // 4. Header Text: "WHEAT"
  // Screen-left is +Z, screen-right is -Z
  const textY = centerY + 0.038;
  const tThick = 0.0018;
  const strokeW = 0.0022;

  function addCharStroke(name, y, z, len, isVert, rotX = 0) {
    const g = isVert ? boxGeo(tThick, len, strokeW) : boxGeo(tThick, strokeW, len);
    createPart(name, g, m.trim, {
      parent: labelNode,
      position: [0, textY + y, z],
      rotation: [rotX, 0, 0]
    });
  }

  // 'W' around Z = +0.028
  addCharStroke('W_1', 0, 0.034, 0.015, true, 10);
  addCharStroke('W_2', 0, 0.030, 0.015, true, -10);
  addCharStroke('W_3', 0, 0.026, 0.015, true, 10);
  addCharStroke('W_4', 0, 0.022, 0.015, true, -10);

  // 'H' around Z = +0.014
  addCharStroke('H_l', 0, 0.017, 0.015, true);
  addCharStroke('H_r', 0, 0.011, 0.015, true);
  addCharStroke('H_mid', 0, 0.014, 0.006, false);

  // 'E' around Z = +0.001
  addCharStroke('E_spine', 0, 0.004, 0.015, true);
  addCharStroke('E_top', 0.0065, 0.000, 0.007, false);
  addCharStroke('E_mid', 0, 0.001, 0.005, false);
  addCharStroke('E_bot', -0.0065, 0.000, 0.007, false);

  // 'A' around Z = -0.012
  addCharStroke('A_l', 0, -0.009, 0.015, true, -12);
  addCharStroke('A_r', 0, -0.015, 0.015, true, 12);
  addCharStroke('A_cross', -0.001, -0.012, 0.006, false);

  // 'T' around Z = -0.025
  addCharStroke('T_top', 0.0065, -0.025, 0.010, false);
  addCharStroke('T_stem', 0, -0.025, 0.015, true);

  // 5. Wheat Ear Icon (golden stalk + chevron grain kernels)
  const iconNode = createPivot('crop_icon', [0, centerY - 0.016, 0], labelNode);

  // Central stalk
  createPart('WheatStalk', boxGeo(0.002, 0.052, 0.0024), m.wheatGold, {
    parent: iconNode,
    position: [0, -0.014, 0.002],
    rotation: [-6, 0, 0]
  });

  // Lower support leaves (two curving blades at base of stalk)
  createPart('BaseLeafL', boxGeo(0.002, 0.024, 0.003), m.wheatGold, {
    parent: iconNode,
    position: [0, -0.026, 0.012],
    rotation: [-38, 0, 0]
  });
  createPart('BaseLeafR', boxGeo(0.002, 0.024, 0.003), m.wheatGold, {
    parent: iconNode,
    position: [0, -0.026, -0.008],
    rotation: [38, 0, 0]
  });

  // Top apical grain kernel
  createPart('ApexGrain', boxGeo(0.002, 0.015, 0.007), m.wheatGold, {
    parent: iconNode,
    position: [0, 0.028, -0.003],
    rotation: [12, 0, 0]
  });

  // Alternating lateral grains (4 pairs ascending)
  const grains = [
    { y: 0.018, z: 0.007, rot: -34, name: 'Grain_4L' },
    { y: 0.014, z: -0.010, rot: 34, name: 'Grain_4R' },
    { y: 0.006, z: 0.009, rot: -38, name: 'Grain_3L' },
    { y: 0.002, z: -0.011, rot: 38, name: 'Grain_3R' },
    { y: -0.006, z: 0.010, rot: -42, name: 'Grain_2L' },
    { y: -0.010, z: -0.012, rot: 42, name: 'Grain_2R' },
    { y: -0.018, z: 0.009, rot: -46, name: 'Grain_1L' },
    { y: -0.022, z: -0.010, rot: 46, name: 'Grain_1R' }
  ];

  for (const g of grains) {
    createPart(g.name, boxGeo(0.002, 0.013, 0.007), m.wheatGold, {
      parent: iconNode,
      position: [0, g.y, g.z],
      rotation: [g.rot, 0, 0]
    });
  }

  return root;
}
